<script setup lang="ts">import{reactive,ref}from'vue';import{wmApi}from'../api';import{ApiError,useAuthStore}from'@leadnews/shared';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';const f=reactive({name:'',password:''}),busy=ref(false),a=useAuthStore(),r=useRouter();async function go(){busy.value=true;try{const x=await wmApi.login(f.name,f.password);a.login(x.token,{id:x.userId,nickname:x.nickname},'WEMEDIA');r.push('/')}catch(e){ElMessage.error(e instanceof ApiError?e.message:'登录失败')}finally{busy.value=false}}</script><template><main class="login-wrap"><section class="login-card"><div class="eyebrow">CREATOR STUDIO</div><h1>创作，从这里开始</h1><el-form class="stack" style="margin-top:24px" @submit.prevent="go"><el-input v-model="f.name" placeholder="账号"/><el-input v-model="f.password" type="password" show-password placeholder="密码"/><el-button type="primary" native-type="submit" :loading="busy">进入创作台</el-button></el-form></section></main></template>
